entries[7560] = { ["name"] = "Bauplan: Gnomenuniversalfernbedienung", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Gnomenuniversalfernbedienung.\nBenötigt Klassische Ingenieurskunst (125)\nVerkaufspreis:\nGnomenuniversalfernbedienung\nWird beim Anlegen gebunden\nSchmuck\nBenutzen: Ermöglicht für kurze Zeit die Kontrolle eines mechanischen Ziels. Manchmal funktioniert das allerdings nicht und lässt die Maschine einfach erstarren oder macht sie sehr, sehr ärgerlich. Gnomeningenieurskunst vom Feinsten. (3 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (125)\nVerkaufspreis:\nBenötigt Bronzebarren (6), Surrendes bronzenes Dingsda , Fläschchen Öl (2), Tigerauge , Malachit" }
entries[7561] = { ["name"] = "Bauplan: Goblinüberbrückungskabel", ["text"] = "Benutzen: Lehrt Euch die Herstellung der Goblinüberbrückungskabel.\nBenötigt Klassische Ingenieurskunst (165)\nVerkaufspreis:\nGoblinüberbrückungskabel\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Verbündeten ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (165)\nVerkaufspreis:\nBenötigt Eisenbarren (6), Surrendes bronzenes Dingsda (2), Fläschchen Öl (2), Seidenstoff (2), Schattenedelstein (2), Verschmorte Verkabelung" }
